s("ds/dsu_with_potentials.hpp",{t({"template <class S, auto op, auto inv>","struct dsu_with_potentials {","  static_assert(std::is_convertible_v<decltype(op), std::function<S(S, S)>>,","                \"op must work as S(S, S)\");","  static_assert(std::is_convertible_v<decltype(inv), std::function<S(S)>>,","                \"inv must work as S(S)\");",""," private:","  std::vector<int> root;","  std::vector<S> V;",""," public:","  dsu_with_potentials() {}","  dsu_with_potentials(int n, S zero) : root(n, -1), V(n, zero) {}","","  int leader(int a) {","    if (root[a] < 0) return a;","    int p = leader(root[a]);","    V[a] = op(V[a], V[root[a]]);","    return root[a] = p;","  }","","  bool merge(int a, int b, S v) {","    int a2 = leader(a), b2 = leader(b);","    if (a2 == b2) return op(V[b], inv(V[a])) == v;","    if (root[a2] > root[b2]) {","      std::swap(a2, b2);","      std::swap(a, b);","      v = inv(v);","    }","    root[a2] += root[b2];","    root[b2] = a2;","    V[b2] = op(op(v, V[a]), inv(V[b]));","    return true;","  }","","  bool same(int a, int b) { return leader(a) == leader(b); }","","  int size(int a) { return -root[leader(a)]; }","","  S potential(int a) {","    leader(a);","    return V[a];","  }","","  S voltage(int a, int b) { return op(potential(b), inv(potential(a))); }","};"})}),
s("ds/dsu_with_rollbacks.hpp",{t({"struct dsu_with_rollbacks {"," private:","  std::vector<int> root, saves;","  std::vector<std::tuple<int, int, int>> history;",""," public:","  dsu_with_rollbacks() {}","  dsu_with_rollbacks(int n) : root(n, -1), saves({0}) {}","","  // https://codeforces.com/blog/entry/90340?#comment-787571","  // O(\\log(N))","  int leader(int a) {","    if (root[a] < 0) return a;","    return leader(root[a]);","  }","","  int merge(int a, int b) {","    if ((a = leader(a)) == (b = leader(b))) return a;","    if (root[a] > root[b]) {","      std::swap(a, b);","    }","    history.push_back({a, b, root[b]});","    root[a] += root[b];","    root[b] = a;","    return a;","  }","","  bool same(int a, int b) { return leader(a) == leader(b); }","","  int size(int a) { return -root[leader(a)]; }","","  void save() { saves.push_back(history.size()); }","","  void rollback() {","    while ((int) history.size() > saves.back()) {","      auto [a, b, size] = history.back();","      history.pop_back();","      root[a] -= size;","      root[b] = size;","    }","    saves.pop_back();","  }","};"})}),
s("ds/dsu.hpp",{t({"struct dsu {"," public:","  dsu() : _n(0) {}","  explicit dsu(int n) : _n(n), parent_or_size(n, -1) {}","","  int merge(int a, int b) {","    assert(0 <= a && a < _n);","    assert(0 <= b && b < _n);","    int x = leader(a), y = leader(b);","    if (x == y) return x;","    if (-parent_or_size[x] < -parent_or_size[y]) std::swap(x, y);","    parent_or_size[x] += parent_or_size[y];","    parent_or_size[y] = x;","    return x;","  }","","  bool same(int a, int b) {","    assert(0 <= a && a < _n);","    assert(0 <= b && b < _n);","    return leader(a) == leader(b);","  }","","  int leader(int a) {","    assert(0 <= a && a < _n);","    return _leader(a);","  }","","  int size(int a) {","    assert(0 <= a && a < _n);","    return -parent_or_size[leader(a)];","  }","","  std::vector<std::vector<int>> groups() {","    std::vector<int> leader_buf(_n), group_size(_n);","    for (int i = 0; i < _n; i++) {","      leader_buf[i] = leader(i);","      group_size[leader_buf[i]]++;","    }","    std::vector<std::vector<int>> result(_n);","    for (int i = 0; i < _n; i++) {","      result[i].reserve(group_size[i]);","    }","    for (int i = 0; i < _n; i++) {","      result[leader_buf[i]].push_back(i);","    }","    result.erase(","        std::remove_if(result.begin(), result.end(),","                       [&](const std::vector<int> &v) { return v.empty(); }),","        result.end());","    return result;","  }",""," private:","  int _n;","  // root node: -1 * component size","  // otherwise: parent","  std::vector<int> parent_or_size;","","  int _leader(int a) {","    if (parent_or_size[a] < 0) return a;","    return parent_or_size[a] = _leader(parent_or_size[a]);","  }","};"})}),
s("ds/FT.hpp",{t({"struct FT {","  vi s;","  FT(int n) : s(n) {}","  void update(int i, int dif) {  // a[i] += dif","    for (; i < sz(s); i |= i + 1) s[i] += dif;","  }","  int query(int i) {  // sum of values in [0, i)","    int r = 0;","    for (; i > 0; i &= i - 1) r += s[i - 1];","    return r;","  }","  int lower_bound(int sum) {  // min i st sum of [0, i] >= sum","    // Returns n if no sum is >= sum, or -1 if empty sum is.","    // (assumes a[i] >= 0)","    if (sum <= 0) return -1;","    int i = 0;","    for (int pw = 1 << 25; pw; pw >>= 1) {","      if (i + pw <= sz(s) && s[i + pw - 1] < sum) i += pw, sum -= s[i - 1];","    }","    return i;","  }","};"})}),
s("ds/implicit_treap.hpp",{t({"// TODO: replace size with a general property generic","template <class T>","struct implicit_treap {"," private:","  static std::mt19937 rng;","","  struct node {","    T v;","    node *l, *r;","    int y, size;","","    node(T _v, int _y) : v(_v), l(nullptr), r(nullptr), y(_y), size(0) {}","    node(T _v) : node(_v, rng()) {}","  };","","  node *root;","","  static int safe_size(node *a) { return a == nullptr ? 0 : a->size; }","","  static node *safe_copy(node *a) {","    if (a == nullptr) return nullptr;","    node *a2 = new node(*a);","    a2->l = safe_copy(a->l);","    a2->r = safe_copy(a->r);","    return a2;","  }","","  static void safe_free(node *a) {","    if (a == nullptr) return;","    safe_free(a->l);","    safe_free(a->r);","    free(a);","  }","","  static void safe_pull(node *a) {","    if (a == nullptr) return;","    a->size = safe_size(a->l) + 1 + safe_size(a->r);","  }","","  static node *merge(node *l, node *r) {","    auto dfs = [&](auto self, node *&a, node *l, node *r) -> void {","      if (l == nullptr) {","        a = r;","      } else if (r == nullptr) {","        a = l;","      } else if (l->y >= r->y) {","        self(self, l->r, l->r, r);","        a = l;","      } else {","        self(self, r->l, l, r->l);","        a = r;","      }","      safe_pull(a);","    };","    node *rv;","    dfs(dfs, rv, l, r);","    return rv;","  }","","  static std::pair<node *, node *> split(node *a, int i) {","    auto dfs = [&](auto self, node *a, node *&l, node *&r, int i) -> void {","      if (a == nullptr) {","        l = r = nullptr;","        return;","      }","      if (i <= safe_size(a->l)) {","        self(self, a->l, l, a->l, i);","        r = a;","      } else {","        self(self, a->r, a->r, r, i - (1 + safe_size(a->l)));","        l = a;","      }","      safe_pull(a);","    };","    node *l, *r;","    dfs(dfs, a, l, r, i);","    return {l, r};","  }","","  implicit_treap(node *_root) : root(_root) {}","","  node *get_node(int i) {","    assert(0 <= i and i < size());","    auto dfs = [&](auto self, node *a, int i) -> node * {","      if (i == safe_size(a->l)) {","        return a;","      } else if (i < safe_size(a->l)) {","        return self(self, a->l, i);","      } else {","        return self(self, a->r, i - (1 + safe_size(a->l)));","      }","    };","    return dfs(dfs, root, i);","  };",""," public:","  implicit_treap() : root(nullptr) {}","","  implicit_treap(const std::vector<int> &v) {","    auto dfs_heapify = [&](auto self, node *a) -> void {","      if (a == nullptr) return;","      node *b = a;","      if (a->l != nullptr and a->l->y > b->y) {","        b = a->l;","      }","      if (a->r != nullptr and a->r->y > b->y) {","        b = a->r;","      }","      if (b != a) {","        std::swap(a->y, b->y);","        self(self, b);","      }","    };","","    auto dfs_build = [&](auto self, int l, int r) -> node * {","      if (l == r) return nullptr;","      int m = l + (r - l) / 2;","      node *a = new node(v[m]);","      a->l = self(self, l, m);","      a->r = self(self, m + 1, r);","      dfs_heapify(dfs_heapify, a);","      safe_pull(a);","      return a;","    };","    root = dfs_build(dfs_build, 0, v.size());","  }","","  implicit_treap(int n, T v) : implicit_treap(std::vector<T>(n, v)) {}","","  ~implicit_treap() { safe_free(root); }","","  int size() const { return safe_size(root); }","","  void insert(int i, T v) {","    assert(0 <= i and i <= size());","    auto [l, r] = split(root, i);","    root = merge(merge(l, new node(v)), r);","  }","","  void erase(int i) {","    assert(0 <= i and i < size());","    auto [l1, r1] = split(root, i);","    auto [l2, r2] = split(r1, 1);","    safe_free(l2);","    root = merge(l1, r2);","  }","","  void set(int i, T v) { get_node(i)->v = v; }","","  T get(int i) { return get_node(i)->v; }","};","template <class T>","std::mt19937 implicit_treap<T>::rng(time(nullptr));"})}),
s("ds/sparse_table.hpp",{t({"template <class S, auto op, auto e>","struct sparse_table {","  static_assert(std::is_convertible_v<decltype(op), std::function<S(S, S)>>,","                \"op must work as S(S, S)\");","  static_assert(std::is_convertible_v<decltype(e), std::function<S()>>,","                \"e must work as S()\");",""," private:","  int n;","  std::vector<std::vector<S>> table;",""," public:","  sparse_table() {}","  sparse_table(const std::vector<S> &v)","      : n(v.size()), table(std::__lg(n) + 1, std::vector<S>(n, e())) {","    std::copy(v.begin(), v.end(), table[0].begin());","    for (int i = 1; i < (int) table.size(); i++) {","      for (int j = 0; j + (1 << i) <= n; j++) {","        table[i][j] = op(table[i - 1][j], table[i - 1][j + (1 << (i - 1))]);","      }","    }","  }","","  S prod(int l, int r) const {","    if (l >= r) return e();","    int d = std::__lg(r - l);","    return op(table[d][l], table[d][r - (1 << d)]);","  }","};"})}),
s("misc/pratt_parser.hpp",{t({"// TODO: write pratt parser","//","// the way i understand it is that there's 3 main functions:","//","// 1. parse operand","// 2. parse operator","// 3. get binding power","//","// parsing operands is for parsing stuff that can't really be divided by an","// operator, so stuff like numbers, symbols, unary operators (negation, etc.),","// or parentheses","//","// parsing operators takes an lhs operand and an operator and calls a function","// to parse the rhs operand and then combines them as necessary","//","// binding power decides when to stop parsing for a subexpression. if an","// operator's binding power is too small, that means we can't use the operator","// just yet; we need to handle the higher binding power operators first. so i","// guess in simple terms, binding power is just \"what should i do first?\". i","// think left/right associativity comes into play when dealing with two binding","// powers that are equal","//","// i think we can implement this nicely with a stack? or cleaner with recursion?","//","// i think operand and operator parsing are forced to have access to the parsing","// context to handle stuff with trailing tokens like parentheses or functions","//","// honestly though, i feel like trailing tokens aren't that big a deal because","// they don't provide any new information. i believe we can make these a no-op,","// at least for what a pratt parser is supposed to provide"})}),
s("string/SuffixArray.hpp",{t({"struct SuffixArray {","  vi sa, lcp;","  SuffixArray(string &s, int lim = 256) {  // or basic_string<int>","    int n = sz(s) + 1, k = 0, a, b;","    vi x(all(s)), y(n), ws(max(n, lim));","    x.pb(0), sa = lcp = y, iota(all(sa), 0);","    for (int j = 0, p = 0; p < n; j = max(1ll, j * 2), lim = p) {","      p = j, iota(all(y), n - j);","      rep(i, 0, n) if (sa[i] >= j) y[p++] = sa[i] - j;","      fill(all(ws), 0);","      rep(i, 0, n) ws[x[i]]++;","      rep(i, 1, lim) ws[i] += ws[i - 1];","      for (int i = n; i--;) sa[--ws[x[y[i]]]] = y[i];","      swap(x, y), p = 1, x[sa[0]] = 0;","      rep(i, 1, n) a = sa[i - 1], b = sa[i],","                   x[b] = (y[a] == y[b] && y[a + j] == y[b + j]) ? p - 1 : p++;","    }","    for (int i = 0, j; i < n - 1; lcp[x[i++]] = k)","      for (k &&k--, j = sa[x[i] - 1]; s[i + k] == s[j + k]; k++);","  }","};"})}),
s("tree/sack.hpp",{t({"void sack(const std::function<void(int)> &insert,","          const std::function<void()> &clear,","          const std::function<void(int)> &callback,","          const std::vector<std::vector<int>> &adj, int r = 0) {","  int n = adj.size();","","  std::vector<int> order(n);","  int t = 0;","  auto dfs = [&](auto self, int a, int p) -> void {","    order[t] = a;","    t++;","","    int l = t;","    for (int i = 1; i < (int) adj[a].size(); i++) {","      if (adj[a][i] == p) continue;","      self(self, adj[a][i], a);","      clear();","    }","    int r = t;","","    if ((int) adj[a].size() > 0 and adj[a][0] != p) {","      self(self, adj[a][0], a);","      for (int i = l; i < r; i++) {","        insert(order[i]);","      }","    }","    insert(a);","","    callback(a);","  };","  dfs(dfs, r, -1);","}"})}),
s("tree/sort_hld.hpp",{t({"void sort_hld(std::vector<std::vector<int>> &adj, int r = 0) {","  auto dfs = [&](auto self, int a, int p) -> int {","    int rv = 1, nmax = 0;","    for (int i = 0; i < (int) adj[a].size(); i++) {","      if (adj[a][i] == p) {","        std::swap(adj[a][i], adj[a].back());","      }","","      if (adj[a][i] == p) continue;","      int n = self(self, adj[a][i], a);","      rv += n;","","      if (i == 0) {","        nmax = n;","      } else {","        if (n > nmax) {","          std::swap(adj[a][0], adj[a][i]);","          nmax = n;","        }","      }","    }","    return rv;","  };","  dfs(dfs, r, -1);","}"})}),
